import { RobotModel } from '../../types/robot';
import { CodeExportOptions } from '../../types/codeExport';

export function generateCppCode(
  robot: RobotModel,
  currentAnglesDeg: number[],
  options: CodeExportOptions
): string {
  let code = `/**
 * =============================================================================
 * Robotics Kinematics & Geometric Jacobian in C++17
 * Robot: ${robot.name} (${robot.manufacturer}) - ${robot.dof} DOF
 * Generated by RoboCAD 3D - Multi-Platform Code Exporter
 * Compatible with University Robotics Syllabus (cppnb / Eigen3)
 * =============================================================================
 * Compilation:
 *   g++ -O3 -std=c++17 ${robot.id.toLowerCase()}_kinematics.cpp -o ${robot.id.toLowerCase()}_kinematics
 * Optional with Eigen:
 *   g++ -O3 -std=c++17 -I /usr/include/eigen3 ${robot.id.toLowerCase()}_kinematics.cpp -o ${robot.id.toLowerCase()}_kinematics
 * =============================================================================
 */

#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>
#include <string>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

// Denavit-Hartenberg Standard Parameter Struct
struct DHParameter {
    int jointIndex;
    double thetaOffsetRad;
    double d;        // mm
    double a;        // mm
    double alphaRad; // radians
    double qMinDeg;
    double qMaxDeg;
};

// 4x4 Homogeneous Transformation Matrix Representation
struct Transform4 {
    double m[4][4];

    static Transform4 identity() {
        Transform4 res{};
        for (int i = 0; i < 4; ++i) res.m[i][i] = 1.0;
        return res;
    }

    Transform4 operator*(const Transform4& other) const {
        Transform4 res{};
        for (int i = 0; i < 4; ++i) {
            for (int j = 0; j < 4; ++j) {
                res.m[i][j] = 0.0;
                for (int k = 0; k < 4; ++k) {
                    res.m[i][j] += m[i][k] * other.m[k][j];
                }
            }
        }
        return res;
    }

    void print(const std::string& title = "Transform Matrix") const {
        std::cout << title << ":\\n";
        for (int i = 0; i < 4; ++i) {
            std::cout << "  [ ";
            for (int j = 0; j < 4; ++j) {
                std::cout << std::fixed << std::setw(10) << std::setprecision(4) << m[i][j] << " ";
            }
            std::cout << "]\\n";
        }
    }
};

class ${robot.id}Robot {
public:
    std::string name = "${robot.name}";
    int dof = ${robot.dof};
    std::vector<DHParameter> dh;

    ${robot.id}Robot() {
        // Standard D-H Parameters: {jointIndex, thetaOffsetRad, d(mm), a(mm), alphaRad, qMin, qMax}
`;

  robot.joints.forEach((joint, idx) => {
    const thetaOffsetRad = ((joint.thetaOffsetDeg * Math.PI) / 180).toFixed(6);
    const dVal = joint.d.toFixed(2);
    const aVal = joint.a.toFixed(2);
    const alphaRad = ((joint.alphaDeg * Math.PI) / 180).toFixed(6);
    const qMin = joint.qMinDeg.toFixed(1);
    const qMax = joint.qMaxDeg.toFixed(1);

    code += `        dh.push_back({${idx + 1}, ${thetaOffsetRad}, ${dVal}, ${aVal}, ${alphaRad}, ${qMin}, ${qMax}}); // Joint ${idx + 1}\n`;
  });

  code += `    }

    /**
     * Compute individual homogeneous transformation matrix A_i(theta_i)
     * Standard Denavit-Hartenberg Convention
     */
    Transform4 computeLinkTransform(int i, double thetaRad) const {
        const auto& p = dh[i];
        double th = thetaRad + p.thetaOffsetRad;
        double ct = std::cos(th);
        double st = std::sin(th);
        double ca = std::cos(p.alphaRad);
        double sa = std::sin(p.alphaRad);

        Transform4 A{};
        A.m[0][0] = ct;       A.m[0][1] = -st * ca;  A.m[0][2] =  st * sa;  A.m[0][3] = p.a * ct;
        A.m[1][0] = st;       A.m[1][1] =  ct * ca;  A.m[1][2] = -ct * sa;  A.m[1][3] = p.a * st;
        A.m[2][0] = 0.0;      A.m[2][1] =  sa;       A.m[2][2] =  ca;       A.m[2][3] = p.d;
        A.m[3][0] = 0.0;      A.m[3][1] =  0.0;      A.m[3][2] =  0.0;      A.m[3][3] = 1.0;
        return A;
    }

    /**
     * Forward Kinematics (FK): returns cumulative transforms for each frame
     */
    std::vector<Transform4> forwardKinematicsCumulative(const std::vector<double>& qRad) const {
        std::vector<Transform4> T(dof + 1);
        T[0] = Transform4::identity(); // Base frame {0}

        for (int i = 0; i < dof; ++i) {
            Transform4 A_i = computeLinkTransform(i, qRad[i]);
            T[i + 1] = T[i] * A_i;
        }
        return T;
    }
`;

  if (options.includeJacobian) {
    code += `
    /**
     * Geometric Jacobian computation in base frame {0}
     * J = [ J_v ] = [ z_{i-1} x (p_e - p_{i-1}) ]
     *     [ J_w ]   [           z_{i-1}         ]
     */
    std::vector<std::vector<double>> computeGeometricJacobian(const std::vector<double>& qRad) const {
        auto T = forwardKinematicsCumulative(qRad);
        // End-effector position p_e
        double pe_x = T[dof].m[0][3];
        double pe_y = T[dof].m[1][3];
        double pe_z = T[dof].m[2][3];

        std::vector<std::vector<double>> J(6, std::vector<double>(dof, 0.0));

        for (int i = 0; i < dof; ++i) {
            // z_{i-1} axis is the 3rd column of rotation matrix T[i]
            double z_x = T[i].m[0][2];
            double z_y = T[i].m[1][2];
            double z_z = T[i].m[2][2];

            // p_{i-1} origin position
            double pi_x = T[i].m[0][3];
            double pi_y = T[i].m[1][3];
            double pi_z = T[i].m[2][3];

            // Vector (p_e - p_{i-1})
            double rx = pe_x - pi_x;
            double ry = pe_y - pi_y;
            double rz = pe_z - pi_z;

            // Cross product: z_{i-1} x r
            double jv_x = (z_y * rz - z_z * ry) / 1000.0; // convert mm to m
            double jv_y = (z_z * rx - z_x * rz) / 1000.0;
            double jv_z = (z_x * ry - z_y * rx) / 1000.0;

            // Linear velocity Jacobian J_v (m/s / rad/s)
            J[0][i] = jv_x;
            J[1][i] = jv_y;
            J[2][i] = jv_z;

            // Angular velocity Jacobian J_w (rad/s / rad/s)
            J[3][i] = z_x;
            J[4][i] = z_y;
            J[5][i] = z_z;
        }

        return J;
    }
`;
  }

  code += `};

int main() {
    std::cout << "=========================================================\\n";
    std::cout << "Robotics Analytical Engine: ${robot.name}\\n";
    std::cout << "=========================================================\\n";

    ${robot.id}Robot robot;

    // Joint angles configuration in degrees
    std::vector<double> qDeg = {${options.useCurrentAngles ? currentAnglesDeg.map((a) => a.toFixed(2)).join(', ') : '0.0, 30.0, -45.0, 0.0, 30.0, 0.0'}};
    std::vector<double> qRad(robot.dof);

    std::cout << "Joint Configuration:\\n";
    for (int i = 0; i < robot.dof; ++i) {
        qRad[i] = qDeg[i] * M_PI / 180.0;
        std::cout << "  Joint " << (i + 1) << ": " << std::setw(8) << qDeg[i] 
                  << " deg (" << std::setw(8) << qRad[i] << " rad)\\n";
    }

    // 1. Forward Kinematics
    auto T_all = robot.forwardKinematicsCumulative(qRad);
    const auto& T_tcp = T_all[robot.dof];
    
    std::cout << "\\n[1] Forward Kinematics TCP Transformation Matrix (T_0_" << robot.dof << "):\\n";
    T_tcp.print();

    std::cout << "\\nTCP Position (mm):\\n";
    std::cout << "  X: " << std::fixed << std::setprecision(2) << T_tcp.m[0][3] << " mm\\n";
    std::cout << "  Y: " << std::fixed << std::setprecision(2) << T_tcp.m[1][3] << " mm\\n";
    std::cout << "  Z: " << std::fixed << std::setprecision(2) << T_tcp.m[2][3] << " mm\\n";
`;

  if (options.includeJacobian) {
    code += `
    // 2. Geometric Jacobian Matrix
    auto J = robot.computeGeometricJacobian(qRad);
    std::cout << "\\n[2] Geometric Jacobian Matrix (6x" << robot.dof << ") [Top: J_v (m/s), Bottom: J_w (rad/s)]:\\n";
    for (int r = 0; r < 6; ++r) {
        std::cout << "  [ ";
        for (int c = 0; c < robot.dof; ++c) {
            std::cout << std::fixed << std::setw(9) << std::setprecision(4) << J[r][c] << " ";
        }
        std::cout << "]\\n";
    }
`;
  }

  code += `
    std::cout << "\\nCalculation completed successfully.\\n";
    return 0;
}
`;

  return code;
}
